SELECT COUNT(ct.*) from cm_contents ct left join cm_doctor dc on dc.seq = ct.doctor_seq and dc.is_enabled left join cm_disease cd on cd.seq = ct.disease_seq and cd.is_enabled
ct.is_enabled AND ct.is_viewed AND ct.lang = #{lang}
AND ct.disease_seq = #{diseaseSeq}
AND (ct.title ILIKE CONCAT('%', #{searchText}, '%') OR ct.contents ILIKE CONCAT('%', #{searchText}, '%'))

select ct.seq, dc.name as doctorName, dp.name as departmentName, ct.doctor_seq, cd.seq as diseaseSeq, cd.name as diseaseName, ct.title, ct.contents, ct.interest, ct.contents_updated_at, ct.image, ct.disease, ct.view_count, ct.is_viewed as viewed, to_char(cast(ct.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt, to_char(cast(ct.updated_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as updatedAt, case when (cf.contents_seq is not null) then 'Y' else 'N' end as favoriteYn from cm_contents ct left join cm_doctor dc on dc.seq = ct.doctor_seq and dc.is_enabled left join cm_department dp on dp.seq = dc.department_seq and dp.is_enabled left join cm_disease cd on cd.seq = ct.disease_seq and cd.is_enabled left join cm_contents_favorite cf on cf.contents_seq = ct.seq and cf.is_enabled and cf.account_seq = #{acSeq}
ct.is_enabled AND ct.is_viewed AND ct.lang = #{lang}
AND ct.disease_seq = #{diseaseSeq}
AND (ct.title ILIKE CONCAT('%', #{searchText}, '%') OR ct.contents ILIKE CONCAT('%', #{searchText}, '%'))
ORDER BY ct.seq DESC
LIMIT #{pagination.endNum} OFFSET #{pagination.startNum}

