select seq , priority , video_type_cd , url , use_yn , detail_desc , to_char(created_at,'YYYY_MM_DD HH24:MI:SS') created_at , to_char(updated_at,'YYYY_MM_DD HH24:MI:SS') updated_at , lang from public.cm_contents_video where 1=1
and video_type_cd = #{videoTypeCd}
and use_yn = #{useYn}
and lang = #{lang} order by seq, video_type_cd, priority

select seq , priority , video_type_cd , url , use_yn , detail_desc , to_char(created_at,'YYYY_MM_DD HH24:MI:SS') created_at , to_char(updated_at,'YYYY_MM_DD HH24:MI:SS') updated_at from public.cm_contents_video where 1=1
and video_type_cd = #{videoTypeCd}
and use_yn = #{useYn}
and lang = (select lang from public.account where login_id = #{loginId} and is_enabled = true and is_dropped = false)) order by seq, video_type_cd, priority

